const beats = { камень: "ножницы", ножницы: "бумага", бумага: "камень" };
const winner = (a, b) => (a === b ? "ничья" : beats[a] === b ? "игрок" : "компьютер");
const stats = {};
let p = 0, c = 0;
while (p < 3 && c < 3) {
  const [a, b] = input().split(" ");
  stats[a] = (stats[a] ?? 0) + 1;
  const w = winner(a, b);
  if (w === "игрок") p++;
  if (w === "компьютер") c++;
}
console.log(p === 3 ? "Победил игрок!" : "Победил компьютер!");
let best = null;
for (const m in stats) if (best === null || stats[m] > stats[best]) best = m;
console.log(`Чаще всего: ${best}`);
